#!/usr/bin/env node
import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadConfig } from "./config.js";
import { installLocalPlugin } from "./install.js";
import { PrivacyClient } from "./privacy.js";
export async function main(argv = process.argv.slice(2)) {
    const command = argv[0] ?? "help";
    if (command === "help" || command === "--help" || command === "-h") {
        printHelp();
        return 0;
    }
    if (command === "doctor") {
        return doctor();
    }
    if (command === "install") {
        return install(argv.slice(1));
    }
    if (command === "print-config") {
        const config = loadConfig();
        console.log(JSON.stringify({
            enabled: config.enabled,
            baseUrl: config.baseUrl,
            pseudonymizeUrl: config.pseudonymizeUrl,
            rehydrateUrl: config.rehydrateUrl,
            healthUrl: config.healthUrl,
            strict: config.strict,
            timeoutMs: config.timeoutMs,
            healthTimeoutMs: config.healthTimeoutMs,
            transformSystem: config.transformSystem,
            restoreAssistantText: config.restoreAssistantText,
            restoreToolArgs: config.restoreToolArgs,
            transformToolDefinitions: config.transformToolDefinitions,
            skipKeys: [...config.skipKeys].sort(),
        }, null, 2));
        return 0;
    }
    console.error(`Unknown command: ${command}`);
    printHelp();
    return 2;
}
async function install(argv) {
    let options = {};
    for (let index = 0; index < argv.length; index += 1) {
        const arg = argv[index];
        if (arg === "--global" || arg === "-g") {
            options = { ...options, global: true };
            continue;
        }
        if (arg === "--project") {
            options = { ...options, global: false };
            continue;
        }
        if (arg === "--force" || arg === "-f") {
            options = { ...options, force: true };
            continue;
        }
        if (arg === "--cwd") {
            const value = argv[index + 1];
            if (!value) {
                console.error("install failed: --cwd requires a path");
                return 2;
            }
            options = { ...options, cwd: value };
            index += 1;
            continue;
        }
        if (arg === "--config-dir") {
            const value = argv[index + 1];
            if (!value) {
                console.error("install failed: --config-dir requires a path");
                return 2;
            }
            options = { ...options, configDir: value };
            index += 1;
            continue;
        }
        console.error(`Unknown install option: ${arg}`);
        return 2;
    }
    try {
        const result = await installLocalPlugin(options);
        const state = result.changed ? "installed" : "already installed";
        console.log(`${state} ${result.scope} plugin: ${result.pluginFile}`);
        console.log(`points to: ${result.packageEntryUrl}`);
        return 0;
    }
    catch (error) {
        console.error(`install failed: ${error instanceof Error ? error.message : "unknown error"}`);
        return 1;
    }
}
async function doctor() {
    let config;
    try {
        config = loadConfig();
    }
    catch (error) {
        console.error(`fail  config: ${error instanceof Error ? error.message : "invalid config"}`);
        return 1;
    }
    console.log(`ok    config: base_url=${config.baseUrl}`);
    const client = new PrivacyClient(config);
    const health = await client.health();
    if (!health.ok) {
        console.error(`fail  cloakpipe: ${health.detail}`);
        return 1;
    }
    console.log(`ok    cloakpipe: ${health.detail}`);
    return 0;
}
function printHelp() {
    console.log(`opencode-cloakpipe

Usage:
  opencode-cloakpipe install      Install a local plugin shim into .opencode/plugins
  opencode-cloakpipe doctor       Check CloakPipe connectivity
  opencode-cloakpipe print-config Print resolved non-secret config
  opencode-cloakpipe --help       Show this help

Install options:
  --global, -g          Install into ~/.config/opencode/plugins
  --project             Install into ./.opencode/plugins (default)
  --config-dir <dir>    Install into a custom OpenCode config directory
  --cwd <dir>           Resolve project/custom paths from another directory
  --force, -f           Replace an existing shim
`);
}
const entrypoint = process.argv[1] ? path.resolve(process.argv[1]) : "";
if (entrypoint && fileURLToPath(import.meta.url) === entrypoint) {
    main().then((code) => {
        process.exitCode = code;
    });
}
//# sourceMappingURL=cli.js.map

import { loadConfig } from "./config.js";
import { logSafe, debugSafe } from "./log.js";
import { PrivacyClient, safeErrorDetail } from "./privacy.js";
import { inferSessionID, pseudonymizeMessages, pseudonymizeSystem, pseudonymizeToolDefinition, rehydrateDeep, rehydrateText, } from "./transforms.js";
export const OpencodeCloakPipe = async (ctx, options) => {
    const config = loadConfig(options, process.env, ctx.directory);
    if (!config.enabled) {
        await logSafe(ctx.client, config, "info", "plugin disabled");
        return {};
    }
    const privacy = new PrivacyClient(config);
    await logSafe(ctx.client, config, "info", "plugin initialized", {
        baseUrl: config.baseUrl,
        strict: config.strict,
        transformSystem: config.transformSystem,
        restoreAssistantText: config.restoreAssistantText,
        restoreToolArgs: config.restoreToolArgs,
    });
    const ensureCloakPipe = async (hook) => {
        const health = await privacy.health();
        if (health.ok)
            return true;
        await logSafe(ctx.client, config, config.strict ? "error" : "warn", "cloakpipe unavailable", {
            hook,
            status: health.status ?? null,
            detail: health.detail,
        });
        if (config.strict) {
            throw new Error(`${hook}: CloakPipe is unavailable (${health.detail})`);
        }
        return false;
    };
    const runHook = async (hook, action) => {
        if (!(await ensureCloakPipe(hook)))
            return;
        try {
            const report = await action();
            if (report) {
                await debugSafe(ctx.client, config, "hook transformed text", {
                    hook,
                    visitedStrings: report.visitedStrings,
                    changedStrings: report.changedStrings,
                    skippedKeys: report.skippedKeys,
                });
            }
        }
        catch (error) {
            await logSafe(ctx.client, config, config.strict ? "error" : "warn", "cloakpipe transform failed", {
                hook,
                detail: safeErrorDetail(error),
            });
            if (config.strict) {
                throw new Error(`${hook}: CloakPipe transform failed (${safeErrorDetail(error)})`);
            }
        }
    };
    return {
        "experimental.chat.messages.transform": async (_input, output) => {
            await runHook("experimental.chat.messages.transform", async () => {
                const sessionID = inferSessionID(output.messages);
                const report = await pseudonymizeMessages(output.messages, privacy, config);
                await debugSafe(ctx.client, config, "provider-bound messages pseudonymized", {
                    sessionID: sessionID ?? "unknown",
                    changedStrings: report.changedStrings,
                });
                return report;
            });
        },
        "experimental.chat.system.transform": async (_input, output) => {
            if (!config.transformSystem)
                return;
            await runHook("experimental.chat.system.transform", async () => pseudonymizeSystem(output.system, privacy));
        },
        "experimental.text.complete": async (_input, output) => {
            if (!config.restoreAssistantText || typeof output.text !== "string" || !output.text)
                return;
            await runHook("experimental.text.complete", async () => {
                const restored = await rehydrateText(output.text, privacy);
                output.text = restored.text;
                return {
                    visitedStrings: 1,
                    changedStrings: restored.changed ? 1 : 0,
                    skippedKeys: 0,
                };
            });
        },
        "tool.execute.before": async (_input, output) => {
            if (!config.restoreToolArgs)
                return;
            await runHook("tool.execute.before", async () => rehydrateDeep(output.args, privacy, config));
        },
        "tool.definition": async (_input, output) => {
            if (!config.transformToolDefinitions)
                return;
            await runHook("tool.definition", async () => pseudonymizeToolDefinition(output, privacy, config));
        },
    };
};
export default OpencodeCloakPipe;
//# sourceMappingURL=index.js.map
